// ---------------------------------------------------------------------------
// Parse RAW into a clean, de-duplicated, band-tagged lexicon.
//
// Authoring aid: a token may be suffixed with `-no` to mark a word that was drafted and
// then rejected during curation (wrong length, proper noun, inflection-only, or too
// obscure for a child screener). Those tokens are DROPPED here rather than deleted from
// the source so the curation decision stays visible and reviewable in the diff.
// Any token whose length does not match its declared bucket is also dropped, which makes
// a typo fail closed (the word simply is not in the lexicon) instead of silently
// corrupting the ladder graph.
// ---------------------------------------------------------------------------
const byWord = new Map();
for (const [lenKey, bands] of Object.entries(RAW)) {
  const len = Number(lenKey);
  for (const [bandKey, blob] of Object.entries(bands)) {
    const band = Number(bandKey);
    for (const tok of blob.split(/\s+/)) {
      if (!tok || tok.endsWith('-no')) continue;
      const w = tok.toUpperCase();
      if (!/^[A-Z]+$/.test(w)) continue;
      if (w.length !== len) continue;
      // Highest band (most common) wins if a word was listed twice.
      const prev = byWord.get(w);
      if (prev === undefined || band > prev) byWord.set(w, band);
    }
  }
}

/** Every curated word, sorted, as [word, band] pairs. */
export const ENTRIES = [...byWord.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

const BY_LENGTH = new Map();
for (const [w, band] of ENTRIES) {
  if (!BY_LENGTH.has(w.length)) BY_LENGTH.set(w.length, []);
  BY_LENGTH.get(w.length).push(w);
}

/** Sorted list of words of exactly `n` letters. */
export function wordsOfLength(n) {
  return (BY_LENGTH.get(n) || []).slice();
}

/** Vocabulary band 1..7 (7 = earliest/most frequent), or 0 if the word is not curated. */
export function bandOf(word) {
  return byWord.get(String(word).toUpperCase()) || 0;
}

/** True iff the word is in the curated lexicon. */
export function isWord(word) {
  return byWord.has(String(word).toUpperCase());
}

/** Lengths present in the lexicon, ascending. */
export function lengths() {
  return [...BY_LENGTH.keys()].sort((a, b) => a - b);
}

/** Stable content hash — lets a bank record exactly which lexicon it was solved against. */
export function lexiconHash() {
  return createHash('sha1').update(ENTRIES.map(([w, b]) => `${w}:${b}`).join(',')).digest('hex').slice(0, 16);
}

/** Counts per length (for generator/checker reporting). */
export function sizeReport() {
  const out = {};
  for (const n of lengths()) out[n] = BY_LENGTH.get(n).length;
  out.total = ENTRIES.length;
  return out;
}

if (process.argv[1] && process.argv[1].endsWith('lexicon-child-en.mjs')) {
  console.log(`${LEXICON_ID}  hash=${lexiconHash()}`);
  console.log(JSON.stringify(sizeReport(), null, 2));
}
